  'hm.guide.me.code.x': { en: "Show it to staff so they find you fast. Tap the copy icon to copy it.", zh: "出示给工作人员以便快速找到你。点击复制图标即可复制。", id: "Tunjukkan ke staf agar mereka cepat menemukanmu. Ketuk ikon salin untuk menyalinnya." },
  'hm.guide.me.notif.t': { en: "Notifications", zh: "通知", id: "Notifikasi" },
  'hm.guide.me.notif.x': { en: "Alerts for bookings, orders and rewards turn on by themselves in the app — just allow notifications when your phone asks.", zh: "在应用中，预订、订单和奖励通知会自动开启 — 手机询问时请点允许即可。", id: "Notifikasi booking, pesanan dan hadiah aktif otomatis di aplikasi — cukup izinkan notifikasi saat ponselmu bertanya." },
  'hm.guide.me.lang.t': { en: "Language", zh: "语言", id: "Bahasa" },
  'hm.guide.me.lang.x': { en: "English, 中文 or Bahasa. WhatsApp replies follow the same language.", zh: "English、中文或 Bahasa。WhatsApp 回复也会使用相同语言。", id: "English, 中文, atau Bahasa. Balasan WhatsApp mengikuti bahasa yang sama." },
  'hm.guide.me.edit.t': { en: "Save profile · Update password", zh: "保存资料 · 更新密码", id: "Simpan profil · Ubah kata sandi" },
  'hm.guide.me.edit.x': { en: "Change your photo, name, phone and birthday, or set a new password.", zh: "修改头像、姓名、电话和生日，或设置新密码。", id: "Ubah foto, nama, telepon, dan tanggal lahir, atau atur kata sandi baru." },
  'hm.guide.me.support.t': { en: "Support: FAQ · Chat with admin", zh: "客服：常见问题 · 联系管理员", id: "Bantuan: FAQ · Chat dengan admin" },
  'hm.guide.me.support.x': { en: "Tap a question to see the answer, or chat with our team.", zh: "点击问题查看答案，或与我们的团队聊天。", id: "Ketuk pertanyaan untuk melihat jawabannya, atau chat dengan tim kami." },
  'hm.guide.me.p': { en: "Keep notifications allowed on your phone so you never miss a reward!", zh: "请在手机上保持允许通知，不错过任何奖励！", id: "Biarkan notifikasi tetap diizinkan di ponselmu supaya tidak ketinggalan hadiah!" },

  'hm.guide.done.t': { en: "You're all set!", zh: "一切就绪！", id: "Semua siap!" },
  'hm.guide.done.i': { en: "That's every button in the app. Start by feeding your pet and checking your balances — you can open this guide again from the bottom of Home.", zh: "以上就是应用里的所有按钮。先去喂宠物、看看余额吧 — 你可以在主页底部再次打开本指南。", id: "Itu semua tombol di aplikasi. Mulailah dengan memberi makan peliharaan dan cek saldomu — kamu bisa membuka panduan ini lagi dari bagian bawah Beranda." },
  'hm.guide.done.p': { en: "Have fun at the club. See you inside!", zh: "在俱乐部玩得开心。里面见！", id: "Selamat bersenang-senang di klub. Sampai jumpa di dalam!" },
